import {
	UI_ACTION_JOURNAL_KIND,
	UI_CONTRACT_VERSION,
	canonicalUiAction,
	receiptForUiAction,
	validateUiAction,
	validateUiActionAgainstDocument,
	validateUiActionJournal,
	validateUiActionResult,
	validateUiDocument,
	type UiAction,
	type UiActionJournal,
	type UiActionReceipt,
	type UiActionResult,
	type UiDocument,
	type UiDocumentNode,
	type UiStudyPlanItem,
} from "@keating/learner-contracts";
import type { StorageLike } from "../event-store";

const SHARED_ACTION_STATE_PREFIX = "keating:openui-shared-actions:v1:";

type ActionBaseKey = "schemaVersion" | "documentId" | "documentRevision" | "idempotencyKey";

export type SharedUiActionIntent = UiAction extends infer TAction
	? TAction extends UiAction
		? Omit<TAction, ActionBaseKey>
		: never
	: never;

export interface StoredSharedUiActionState {
	version: 1;
	document: UiDocument;
	journal: UiActionJournal;
}

export interface SharedUiActionDispatch {
	action: UiAction;
	sourceDocument: UiDocument;
	result: UiActionResult;
	receipt: UiActionReceipt;
	document: UiDocument;
	journal: UiActionJournal;
	replayed: boolean;
}

function hashText(value: string): string {
	let hash = 2166136261;
	for (let index = 0; index < value.length; index += 1) {
		hash ^= value.charCodeAt(index);
		hash = Math.imul(hash, 16777619);
	}
	return (hash >>> 0).toString(36);
}

function stableJson(value: unknown): string {
	if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
	if (!value || typeof value !== "object") return JSON.stringify(value) ?? "null";
	return `{${Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
		.map(([key, child]) => `${JSON.stringify(key)}:${stableJson(child)}`)
		.join(",")}}`;
}

export function sharedUiActionStateKey(documentId: string): string {
	return `${SHARED_ACTION_STATE_PREFIX}${encodeURIComponent(documentId)}`;
}

export function emptySharedUiActionJournal(documentId: string): UiActionJournal {
	return {
		kind: UI_ACTION_JOURNAL_KIND,
		schemaVersion: UI_CONTRACT_VERSION,
		documentId,
		receipts: [],
	};
}

function isStoredState(value: unknown): value is StoredSharedUiActionState {
	if (!value || typeof value !== "object" || Array.isArray(value)) return false;
	const candidate = value as Partial<StoredSharedUiActionState>;
	return candidate.version === 1
		&& validateUiDocument(candidate.document)
		&& validateUiActionJournal(candidate.journal)
		&& candidate.document.id === candidate.journal.documentId;
}

/**
 * Load only a strictly validated result newer than the message snapshot. A
 * same-revision content mismatch means the model supplied a competing snapshot,
 * so the message remains authoritative and the stale local journal is ignored.
 */
export function loadSharedUiActionState(
	storage: Pick<StorageLike, "getItem"> | null,
	sourceDocument: UiDocument,
): StoredSharedUiActionState {
	const fallback = {
		version: 1 as const,
		document: structuredClone(sourceDocument),
		journal: emptySharedUiActionJournal(sourceDocument.id),
	};
	if (!storage || !validateUiDocument(sourceDocument)) return fallback;
	try {
		const raw = storage.getItem(sharedUiActionStateKey(sourceDocument.id));
		if (!raw) return fallback;
		const candidate: unknown = JSON.parse(raw);
		if (!isStoredState(candidate) || candidate.document.id !== sourceDocument.id) return fallback;
		if (candidate.document.revision > sourceDocument.revision) return structuredClone(candidate);
		if (candidate.document.revision === sourceDocument.revision
			&& stableJson(candidate.document) === stableJson(sourceDocument)) return structuredClone(candidate);
		return fallback;
	} catch {
		return fallback;
	}
}

export function createSharedUiAction(document: UiDocument, intent: SharedUiActionIntent): UiAction {
	const idempotencyKey = `web-ui-${hashText(stableJson({
		documentId: document.id,
		documentRevision: document.revision,
		intent,
	}))}`;
	const action = {
		...intent,
		schemaVersion: UI_CONTRACT_VERSION,
		documentId: document.id,
		documentRevision: document.revision,
		idempotencyKey,
	} as UiAction;
	if (!validateUiAction(action)) throw new Error("The OpenUI action is invalid.");
	return action;
}

function updatePlanItems(
	items: readonly UiStudyPlanItem[],
	itemId: string,
	completed: boolean,
): UiStudyPlanItem[] {
	return items.map((item) => ({
		...item,
		...(item.id === itemId
			? { status: completed ? "done" as const : "not_started" as const }
			: {}),
		...(item.children
			? { children: updatePlanItems(item.children, itemId, completed) }
			: {}),
	}));
}

function applyActionToNodes(nodes: readonly UiDocumentNode[], action: UiAction): UiDocumentNode[] {
	return nodes.map((node) => {
		if (action.type === "complete-goal-step" && node.type === "goal" && node.id === action.nodeId) {
			const steps = node.steps.map((step) => step.id === action.stepId
				? { ...step, status: "done" as const }
				: step);
			return {
				...node,
				steps,
				status: steps.every((step) => step.status === "done") ? "completed" as const : node.status,
			};
		}
		if (action.type === "complete-plan-item" && node.type === "study-plan" && node.id === action.nodeId && node.items) {
			return { ...node, items: updatePlanItems(node.items, action.itemId, action.completed) };
		}
		if (action.type === "update-notes" && node.type === "notes" && node.id === action.nodeId) {
			return { ...node, value: action.value };
		}
		return node;
	});
}

function completedDocument(source: UiDocument, action: UiAction, now: string): UiDocument {
	const document: UiDocument = {
		...source,
		revision: source.revision + 1,
		lifecycle: action.type === "retry" ? "ready" : source.lifecycle,
		nodes: applyActionToNodes(source.nodes, action),
		updatedAt: now,
	};
	if (!validateUiDocument(document)) throw new Error("The OpenUI action produced an invalid document.");
	return document;
}

/**
 * Web's durable exactly-once boundary. The resulting document and completed
 * receipt are serialized into one localStorage value and committed with one
 * setItem call before any success UI or host learner turn is emitted.
 */
export function dispatchSharedUiAction(
	storage: Pick<StorageLike, "getItem" | "setItem">,
	sourceDocument: UiDocument,
	intent: SharedUiActionIntent,
	now = new Date().toISOString(),
): SharedUiActionDispatch {
	const action = createSharedUiAction(sourceDocument, intent);
	const state = loadSharedUiActionState(storage, sourceDocument);
	const currentDocument = state.document;
	const existing = receiptForUiAction(state.journal, action);
	if (existing) {
		if (!existing.result || existing.state !== "completed" || !existing.result.resultingDocument) {
			throw new Error("This OpenUI action has an incomplete durable receipt.");
		}
		return {
			action,
			sourceDocument: currentDocument,
			result: structuredClone(existing.result),
			receipt: structuredClone(existing),
			document: structuredClone(existing.result.resultingDocument),
			journal: structuredClone(state.journal),
			replayed: true,
		};
	}
	if (!validateUiActionAgainstDocument(action, currentDocument)) {
		throw new Error("This OpenUI action no longer applies to the current document revision.");
	}

	const resultingDocument = completedDocument(currentDocument, action, now);
	const result: UiActionResult = {
		schemaVersion: UI_CONTRACT_VERSION,
		documentId: action.documentId,
		sourceRevision: action.documentRevision,
		actionIdempotencyKey: action.idempotencyKey,
		status: "completed",
		documentLifecycle: resultingDocument.lifecycle,
		resultingDocument,
	};
	if (!validateUiActionResult(result)) throw new Error("The OpenUI completion result is invalid.");
	const receipt: UiActionReceipt = {
		schemaVersion: UI_CONTRACT_VERSION,
		action,
		actionFingerprint: canonicalUiAction(action),
		state: "completed",
		createdAt: now,
		updatedAt: now,
		result,
	};
	const journal: UiActionJournal = {
		...state.journal,
		receipts: [...state.journal.receipts, receipt],
	};
	if (!validateUiActionJournal(journal)) throw new Error("The OpenUI action journal is invalid or full.");
	const next: StoredSharedUiActionState = {
		version: 1,
		document: resultingDocument,
		journal,
	};
	storage.setItem(sharedUiActionStateKey(sourceDocument.id), JSON.stringify(next));
	return {
		action: structuredClone(action),
		sourceDocument: structuredClone(currentDocument),
		result: structuredClone(result),
		receipt: structuredClone(receipt),
		document: structuredClone(resultingDocument),
		journal: structuredClone(journal),
		replayed: false,
	};
}
import {
	createContext,
	useCallback,
	useContext,
	useMemo,
	useState,
	type ReactNode,
} from "react";
import type { UiAction, UiDocument } from "@keating/learner-contracts";
import {
	Renderer,
	type ActionEvent,
	type OpenUIError,
} from "@openuidev/react-lang";
import { CircleAlert, Loader2 } from "lucide-react";
import { css } from "../../../styled-system/css";
import type { StorageLike as EventStoreStorage } from "../event-store";
import { keatingOpenUILibrary } from "./library";
import type {
	KeatingOpenUIAction,
	OpenUIDocumentMetadata,
} from "./types";
import { SharedUiDocumentRenderer } from "./shared-renderer";
import {
	dispatchSharedUiAction,
	loadSharedUiActionState,
	type SharedUiActionIntent,
} from "./shared-actions";

const STATE_KEY_PREFIX = "keating:openui-state:v1:";

interface StoredOpenUIState {
	version: 1;
	updatedAt: number;
	state: Record<string, unknown>;
}

type StorageLike = Pick<EventStoreStorage, "getItem" | "setItem">;

export type KeatingOpenUIActionHandler = (action: KeatingOpenUIAction) => void;

const OpenUIActionContext = createContext<KeatingOpenUIActionHandler | null>(null);

export function KeatingOpenUIActionProvider({
	onAction,
	children,
}: {
	onAction: KeatingOpenUIActionHandler;
	children: ReactNode;
}) {
	return <OpenUIActionContext.Provider value={onAction}>{children}</OpenUIActionContext.Provider>;
}

export function openUIStateKey(documentId: string): string {
	return `${STATE_KEY_PREFIX}${documentId}`;
}

export function loadOpenUIState(
	storage: StorageLike | null,
	metadata: OpenUIDocumentMetadata,
): Record<string, unknown> {
	if (!storage || metadata.lifecycle === "ephemeral") return {};
	try {
		const raw = storage.getItem(openUIStateKey(metadata.id));
		if (!raw) return {};
		const parsed = JSON.parse(raw) as Partial<StoredOpenUIState>;
		return parsed.version === 1 && parsed.state && typeof parsed.state === "object"
			? parsed.state
			: {};
	} catch {
		return {};
	}
}

export function saveOpenUIState(
	storage: StorageLike | null,
	metadata: OpenUIDocumentMetadata,
	state: Record<string, unknown>,
): boolean {
	if (!storage || metadata.lifecycle === "ephemeral") return false;
	try {
		const payload: StoredOpenUIState = { version: 1, updatedAt: Date.now(), state };
		storage.setItem(openUIStateKey(metadata.id), JSON.stringify(payload));
		return true;
	} catch {
		return false;
	}
}

function browserStorage(): StorageLike | null {
	if (typeof window === "undefined") return null;
	try {
		return window.localStorage;
	} catch {
		return null;
	}
}

export function KeatingOpenUIRenderer({
	program,
	document,
	metadata,
	isStreaming = false,
}: {
	program?: string;
	document?: UiDocument;
	metadata: OpenUIDocumentMetadata;
	isStreaming?: boolean;
}) {
	const hostAction = useContext(OpenUIActionContext);
	const [errors, setErrors] = useState<OpenUIError[]>([]);
	const storage = useMemo(browserStorage, []);
	const initialState = useMemo(
		() => loadOpenUIState(storage, metadata),
		[storage, metadata.id, metadata.lifecycle],
	);

	const handleAction = useCallback(
		(event: ActionEvent) => {
			const action: KeatingOpenUIAction = {
				kind: "legacy",
				type: event.type,
				humanFriendlyMessage: event.humanFriendlyMessage,
				params: event.params,
				formState: event.formState,
				formName: event.formName,
				document: metadata,
			};
			hostAction?.(action);
		},
		[hostAction, metadata],
	);

	const handleStateUpdate = useCallback(
		(state: Record<string, unknown>) => {
			saveOpenUIState(storage, metadata, state);
		},
		[storage, metadata],
	);

	return (
		<div
			data-openui-document={metadata.id}
			data-openui-lifecycle={metadata.lifecycle}
			data-openui-revision={metadata.revision}
			aria-busy={isStreaming}
		>
			{isStreaming ? (
				<div className={css({ marginBottom: "0.375rem", display: "flex", alignItems: "center", gap: "0.375rem", fontSize: "0.6875rem", color: "var(--muted-foreground)" })} role="status">
					<Loader2 aria-hidden="true" size={12} className={css({ animation: "spin 1s linear infinite", "@media (prefers-reduced-motion: reduce)": { animation: "none" } })} />
					Building interaction
				</div>
			) : null}
			{document ? <DurableSharedUiDocument key={`${document.id}:${document.revision}`} document={document} metadata={metadata} storage={storage} hostAction={hostAction} /> : program ? (
				<div className={isStreaming ? css({ pointerEvents: "none", opacity: 0.78 }) : undefined}>
					<Renderer
						response={program}
						library={keatingOpenUILibrary}
						isStreaming={isStreaming}
						initialState={initialState}
						onAction={handleAction}
						onStateUpdate={handleStateUpdate}
						onError={setErrors}
					/>
				</div>
			) : null}
			{!isStreaming && errors.length > 0 ? (
				<div className={css({ marginBlock: "0.75rem", display: "flex", alignItems: "flex-start", gap: "0.5rem", borderRadius: "0.5rem", background: "color-mix(in srgb, var(--destructive) 10%, transparent)", padding: "0.75rem", fontSize: "0.75rem", color: "var(--destructive)" })} role="alert">
					<CircleAlert aria-hidden="true" size={15} className={css({ marginTop: "0.0625rem", flexShrink: 0 })} />
					<span>This interaction could not be rendered completely. The surrounding lesson is still available.</span>
				</div>
			) : null}
		</div>
	);
}

function canonicalActionParams(action: UiAction): Record<string, unknown> {
	const {
		schemaVersion: _schemaVersion,
		documentId: _documentId,
		documentRevision: _documentRevision,
		idempotencyKey: _idempotencyKey,
		...params
	} = action;
	return params;
}

function DurableSharedUiDocument({
	document,
	metadata,
	storage,
	hostAction,
}: {
	document: UiDocument;
	metadata: OpenUIDocumentMetadata;
	storage: StorageLike | null;
	hostAction: KeatingOpenUIActionHandler | null;
}) {
	const [state, setState] = useState(() => loadSharedUiActionState(storage, document));
	const [actionError, setActionError] = useState<string | null>(null);

	const handleSharedAction = useCallback((event: { intent: SharedUiActionIntent; humanFriendlyMessage: string }) => {
		if (!storage) {
			setActionError("This interaction could not be saved in this browser. Your entered work is still here; retry after enabling site storage.");
			return false;
		}
		try {
			const dispatched = dispatchSharedUiAction(storage, state.document, event.intent);
			setState({ version: 1, document: dispatched.document, journal: dispatched.journal });
			setActionError(null);
			if (!dispatched.replayed) {
				hostAction?.({
					kind: "canonical",
					type: dispatched.action.type,
					humanFriendlyMessage: event.humanFriendlyMessage,
					params: canonicalActionParams(dispatched.action),
					document: {
						...metadata,
						id: dispatched.sourceDocument.id,
						revision: dispatched.sourceDocument.revision,
					},
					action: dispatched.action,
					sourceDocument: dispatched.sourceDocument,
					receipt: dispatched.receipt,
				});
			}
			return true;
		} catch (cause) {
			setActionError(cause instanceof Error
				? `This interaction was not saved: ${cause.message} Your entered work is still here; retry when ready.`
				: "This interaction was not saved. Your entered work is still here; retry when ready.");
			return false;
		}
	}, [hostAction, metadata, state.document, storage]);

	return <>
		<SharedUiDocumentRenderer
			document={state.document}
			receipts={state.journal.receipts}
			onAction={handleSharedAction}
		/>
		{actionError ? <div className={css({ marginBlock: "0.75rem", borderRadius: "0.5rem", background: "color-mix(in srgb, var(--destructive) 10%, transparent)", padding: "0.75rem", fontSize: "0.75rem", color: "var(--destructive)" })} role="alert">{actionError}</div> : null}
	</>;
}
import {
	canonicalUiAction,
	validateUiActionAgainstDocument,
	validateUiActionCorrelation,
	validateUiActionReceipt,
	validateUiDocument,
} from "@keating/learner-contracts";
import type { CanonicalKeatingOpenUIAction, KeatingOpenUIAction } from "../openui/types";
import { legacyPayloadToUiDocument, type UiActionRequest } from "../ui-protocol";
import type { ConversationRuntime } from "./conversation-runtime";
import { jsonSafe } from "./conversation-runtime";

let fallbackActionSequence = 0;

function actionRequestId(documentId: string, actionType: string): string {
	const unique = typeof crypto !== "undefined" && "randomUUID" in crypto
		? crypto.randomUUID()
		: `${Date.now()}-${++fallbackActionSequence}`;
	return `${documentId}:${actionType}:${unique}`;
}

function canonicalRequest(action: CanonicalKeatingOpenUIAction): UiActionRequest {
	return {
		protocol: "keating.ui",
		version: 1,
		id: `${action.action.documentId}-${action.action.idempotencyKey}`,
		documentId: action.action.documentId,
		documentRevision: action.action.documentRevision,
		actionId: action.action.type,
		createdAt: action.receipt.createdAt,
		payload: jsonSafe({ action: action.action, receipt: action.receipt }) as UiActionRequest["payload"],
	};
}

function recordCanonicalOpenUIAction(runtime: ConversationRuntime, action: CanonicalKeatingOpenUIAction): UiActionRequest {
	if (!validateUiDocument(action.sourceDocument)
		|| !validateUiActionAgainstDocument(action.action, action.sourceDocument)
		|| !validateUiActionReceipt(action.receipt)
		|| action.receipt.state !== "completed"
		|| canonicalUiAction(action.receipt.action) !== canonicalUiAction(action.action)
		|| !action.receipt.result
		|| !validateUiActionCorrelation(action.action, action.receipt.result, action.sourceDocument)
		|| action.document.id !== action.sourceDocument.id
		|| action.document.revision !== action.sourceDocument.revision) {
		throw new Error("Rejected invalid canonical OpenUI action receipt");
	}
	const request = canonicalRequest(action);
	const replay = runtime.replay();
	const existing = replay.uiActions.find((candidate) => candidate.id === request.id);
	if (existing) return request;

	const current = replay.uiDocuments[action.sourceDocument.id];
	if (current && current.revision > action.sourceDocument.revision) {
		throw new Error(`Rejected stale OpenUI document ${action.sourceDocument.id} revision ${action.sourceDocument.revision}`);
	}
	if (!current || current.revision < action.sourceDocument.revision) {
		runtime.emit("ui.document.upserted", {
			document: {
				id: action.sourceDocument.id,
				kind: "shared-openui",
				lifecycle: action.document.lifecycle,
				revision: action.sourceDocument.revision,
				content: jsonSafe(action.sourceDocument),
			},
		});
	}
	runtime.emit("ui.action", {
		action: {
			id: request.id,
			documentId: request.documentId,
			documentRevision: request.documentRevision,
			type: request.actionId,
			params: request.payload,
			humanFriendlyMessage: action.humanFriendlyMessage,
		},
	});
	const resultingDocument = action.receipt.result.resultingDocument;
	if (!resultingDocument) throw new Error("Canonical OpenUI completion is missing its resulting document");
	runtime.emit("ui.document.upserted", {
		document: {
			id: resultingDocument.id,
			kind: "shared-openui",
			lifecycle: action.document.lifecycle,
			revision: resultingDocument.revision,
			content: jsonSafe(resultingDocument),
		},
	});
	if (!runtime.resolveAction(request.id)) throw new Error("Canonical OpenUI action receipt was not resolved");
	return request;
}

export function recordOpenUIAction(runtime: ConversationRuntime, action: KeatingOpenUIAction): UiActionRequest {
	if (action.kind === "canonical") return recordCanonicalOpenUIAction(runtime, action);
	const current = runtime.replay().uiDocuments[action.document.id];
	const revision = action.document.revision;
	if (!current && revision !== 0) {
		throw new Error(`OpenUI document ${action.document.id} must begin at revision 0`);
	}
	if (current && revision < current.revision) {
		throw new Error(`Rejected stale OpenUI document ${action.document.id} revision ${revision}`);
	}
	if (current && revision > current.revision + 1) {
		throw new Error(`OpenUI document ${action.document.id} revision must increment by one`);
	}
	if (!current || revision === current.revision + 1) {
		const document = legacyPayloadToUiDocument("openui", { lifecycle: action.document.lifecycle }, {
			id: action.document.id,
			revision,
			title: action.formName,
		});
		runtime.emit("ui.document.upserted", {
			document: {
				id: document.id,
				kind: document.kind,
				lifecycle: action.document.lifecycle,
				revision: document.revision,
				content: jsonSafe(document),
			},
		});
	}
	const request: UiActionRequest = {
		protocol: "keating.ui",
		version: 1,
		id: actionRequestId(action.document.id, action.type),
		documentId: action.document.id,
		documentRevision: revision,
		actionId: action.type,
		createdAt: new Date().toISOString(),
		payload: jsonSafe({ ...action.params, formState: action.formState }) as Record<string, never>,
	};
	runtime.emit("ui.action", {
			action: {
			id: request.id,
			documentId: request.documentId,
			documentRevision: request.documentRevision,
			type: request.actionId,
			params: request.payload,
			humanFriendlyMessage: action.humanFriendlyMessage,
		},
	});
	return request;
}

import { useState } from "react";
import type { UiActionReceipt, UiDocument, UiDocumentNode, UiQuestion, UiStudyPlanItem } from "@keating/learner-contracts";
import { css } from "../../../styled-system/css";
import { MarkdownBlock } from "../../components/MarkdownBlock";
import { MermaidRenderer } from "../../components/MermaidRenderer";
import type { SharedUiActionIntent } from "./shared-actions";

export interface SharedUiActionEvent {
	intent: SharedUiActionIntent;
	humanFriendlyMessage: string;
}

const panel = css({ marginBlock: "0.75rem", display: "grid", gap: "0.75rem", border: "1px solid var(--border)", borderRadius: "0.75rem", background: "var(--background)", padding: "1rem" });
const section = css({ display: "grid", gap: "0.625rem", borderTop: "1px solid var(--border)", paddingTop: "0.75rem", _first: { borderTop: "none", paddingTop: 0 } });
const button = css({ minHeight: "2.5rem", border: "1px solid var(--border)", borderRadius: "0.5rem", paddingInline: "0.75rem", fontSize: "0.8125rem", fontWeight: 600, cursor: "pointer", _hover: { background: "var(--muted)" }, _focusVisible: { outline: "2px solid var(--ring)", outlineOffset: "2px" } });
const input = css({ width: "100%", minHeight: "2.5rem", border: "1px solid var(--border)", borderRadius: "0.5rem", background: "var(--background)", padding: "0.625rem", color: "var(--foreground)" });

export function SharedUiDocumentRenderer({ document, receipts = [], onAction }: { document: UiDocument; receipts?: UiActionReceipt[]; onAction?: (event: SharedUiActionEvent) => boolean }) {
	const supported = document.supportedSurfaces.includes("web");
	const interactive = document.lifecycle === "ready" && supported;
	const retryable = supported && (document.lifecycle === "failed" || document.lifecycle === "cancelled");
	return <section className={panel} data-shared-openui-document={document.id} data-openui-revision={document.revision}>
		{document.title ? <h3 className={css({ fontSize: "1rem", fontWeight: 700 })}>{document.title}</h3> : null}
		{document.description ? <p className={css({ color: "var(--muted-foreground)", fontSize: "0.8125rem" })}>{document.description}</p> : null}
		{!interactive ? <div role="status" className={css({ border: "1px solid var(--border)", borderRadius: "0.5rem", padding: "0.75rem", color: "var(--muted-foreground)" })}>
			<p>This interaction is {document.lifecycle.replace("_", " ")}. Its content remains available, but controls are disabled.</p>
			{retryable ? <button className={button} type="button" onClick={() => onAction?.({ intent: { type: "retry" }, humanFriendlyMessage: "Retry this interaction" })}>Retry interaction</button> : null}
		</div> : null}
		{document.nodes.map((node) => <SharedNode key={node.id} node={node} receipts={receipts} disabled={!interactive} onAction={onAction} />)}
	</section>;
}

function SharedNode({ node, receipts, disabled, onAction }: { node: UiDocumentNode; receipts: UiActionReceipt[]; disabled: boolean; onAction?: (event: SharedUiActionEvent) => boolean }) {
	if (node.type === "markdown") return <div className={section}><MarkdownBlock content={node.markdown} /></div>;
	if (node.type === "callout") return <aside className={css({ display: "grid", gap: "0.625rem", borderTop: "1px solid var(--border)", borderLeft: "3px solid var(--primary)", paddingTop: "0.75rem", paddingLeft: "0.75rem" })} data-callout-tone={node.tone}>
		<strong>{node.title ?? node.tone}</strong><MarkdownBlock content={node.markdown} />
	</aside>;
	if (node.type === "question") return <Question node={node} receipt={completedNodeReceipt(receipts, node.id, ["submit-answer", "choose-option"])} disabled={disabled} onAction={onAction} />;
	if (node.type === "quiz") return <div className={section}><h4 className={css({ fontWeight: 700 })}>{node.title}</h4>{node.questions.map((question) => <Question key={question.id} node={question} receipt={completedNodeReceipt(receipts, question.id, ["submit-answer", "choose-option"])} disabled={disabled} onAction={onAction} />)}</div>;
	if (node.type === "goal") return <Checklist title={node.title} nodeId={node.id} items={node.steps.map((step) => ({ id: step.id, title: step.title, done: step.status === "done" }))} actionType="complete-goal-step" disabled={disabled} onAction={onAction} />;
	if (node.type === "deck") return <Deck node={node} receipts={receipts.filter((receipt) => receipt.state === "completed" && receipt.action.type === "rate-card" && receipt.action.nodeId === node.id)} disabled={disabled} onAction={onAction} />;
	if (node.type === "study-plan") return node.items ? <Plan nodeId={node.id} title={node.title ?? "Study plan"} overview={node.overview} items={node.items} disabled={disabled} onAction={onAction} /> : <Resource title={node.resource?.title ?? "Study plan"} content={node.resource?.content} uri={node.resource?.uri} />;
	if (node.type === "artifact") return <Resource title={node.resource.title} content={node.resource.content} uri={node.resource.uri} markdown={node.resource.format === "markdown"} />;
	if (node.type === "concept-map") return <div className={section}>{node.title ? <h4 className={css({ fontWeight: 700 })}>{node.title}</h4> : null}<MermaidRenderer content={node.source} /></div>;
	if (node.type === "notes") return <Notes node={node} disabled={disabled} onAction={onAction} />;
	if (node.type === "image") return <RemoteImage node={node} />;
	if (node.type === "media") return <Media node={node} />;
	return <div className={section}><strong>Continue on {node.target}</strong><p>{node.reason}</p><p className={css({ color: "var(--muted-foreground)" })}>{node.context}</p>{node.target === "web" ? <a className={button} href="/">Open Keating web</a> : null}</div>;
}

function completedNodeReceipt(receipts: UiActionReceipt[], nodeId: string, types: UiActionReceipt["action"]["type"][]): UiActionReceipt | undefined {
	for (let index = receipts.length - 1; index >= 0; index -= 1) {
		const receipt = receipts[index];
		if (receipt?.state === "completed" && "nodeId" in receipt.action && receipt.action.nodeId === nodeId && types.includes(receipt.action.type)) return receipt;
	}
	return undefined;
}

function Question({ node, receipt, disabled, onAction }: { node: UiQuestion; receipt?: UiActionReceipt; disabled: boolean; onAction?: (event: SharedUiActionEvent) => boolean }) {
	const savedAction = receipt?.action;
	const savedAnswer = savedAction?.type === "submit-answer" ? savedAction.answer : undefined;
	const savedRows = Array.isArray(savedAnswer) && savedAnswer.every((entry) => typeof entry === "object")
		? savedAnswer as Array<{ item: string; optionId: string; reason?: string }>
		: undefined;
	const [answer, setAnswer] = useState(() => typeof savedAnswer === "string" ? savedAnswer : "");
	const [selected, setSelected] = useState<string[]>(() => savedAction?.type === "choose-option" ? [...savedAction.optionIds] : []);
	const [rowSelections, setRowSelections] = useState<string[]>(() => node.items?.map((item) => savedRows?.find((row) => row.item === item)?.optionId ?? "") ?? []);
	const [rowReasons, setRowReasons] = useState<string[]>(() => node.items?.map((item) => savedRows?.find((row) => row.item === item)?.reason ?? "") ?? []);
	const blankCount = node.blanks?.length ?? (node.prompt.match(/_{3,}|\{\{blank\}\}/g)?.length ?? 0);
	const [blankAnswers, setBlankAnswers] = useState<string[]>(() => Array.isArray(savedAnswer) && savedAnswer.every((entry) => typeof entry === "string")
		? [...savedAnswer]
		: Array.from({ length: blankCount }, () => ""));
	const multiple = node.multiSelect || node.kind === "multi_select";
	const rows = node.kind === "classification" || node.kind === "matching";
	const blanks = node.kind === "blanks" || node.kind === "fill_in";
	const payload = rows
		? (node.items ?? []).map((item, index) => ({ item, optionId: rowSelections[index] ?? "", ...(node.requireReasons ? { reason: rowReasons[index] ?? "" } : {}) }))
		: blanks ? blankAnswers : node.choices ? selected : answer;
	const ready = rows
		? rowSelections.length > 0 && rowSelections.every(Boolean) && (!node.requireReasons || rowReasons.every((reason) => reason.trim().length > 0))
		: blanks ? blankAnswers.length > 0 && blankAnswers.every((entry) => entry.trim().length > 0)
			: node.choices ? selected.length > 0 : answer.trim().length > 0;
	const completed = receipt?.state === "completed";
	const submit = () => onAction?.({
		intent: node.choices && !rows
			? { type: "choose-option", nodeId: node.id, optionIds: selected }
			: { type: "submit-answer", nodeId: node.id, answer: payload },
		humanFriendlyMessage: `Answered: ${node.prompt}`,
	});
	return <fieldset className={section} data-question-kind={node.kind ?? "text"}>
		<legend className={css({ fontWeight: 650 })}>{node.header ?? node.prompt}</legend>
		{node.header ? <p>{node.prompt}</p> : null}
		{rows ? <div className={css({ display: "grid", gap: "0.75rem" })}>{node.items?.map((item, rowIndex) => <div key={`${node.id}-${rowIndex}`} className={css({ display: "grid", gap: "0.375rem", border: "1px solid var(--border)", borderRadius: "0.5rem", padding: "0.625rem" })}>
			<strong>{item}</strong>
			<select disabled={disabled || completed} className={input} aria-label={`${node.choiceLabel ?? "Choice"} for ${item}`} value={rowSelections[rowIndex]} onChange={(event) => setRowSelections((current) => current.map((value, index) => index === rowIndex ? event.currentTarget.value : value))}><option value="">Select…</option>{node.choices?.map((choice) => <option key={choice.id} value={choice.id} disabled={node.kind === "matching" && node.uniqueMatches !== false && rowSelections.some((selected, index) => index !== rowIndex && selected === choice.id)}>{choice.label}</option>)}</select>
			{node.requireReasons ? <input disabled={disabled || completed} className={input} aria-label={`${node.reasonLabel ?? "Reason"} for ${item}`} value={rowReasons[rowIndex]} onChange={(event) => setRowReasons((current) => current.map((value, index) => index === rowIndex ? event.currentTarget.value : value))} placeholder={node.reasonLabel ?? "Reason"} /> : null}
		</div>)}</div>
			: blanks ? <div className={css({ display: "grid", gap: "0.375rem" })}>{blankAnswers.map((value, index) => <input disabled={disabled || completed} key={`${node.id}-blank-${index}`} className={input} aria-label={`Blank ${index + 1}`} value={value} onChange={(event) => setBlankAnswers((current) => current.map((entry, entryIndex) => entryIndex === index ? event.currentTarget.value : entry))} placeholder={node.blanks?.[index]?.placeholder ?? `Blank ${index + 1}`} />)}</div>
				: node.choices ? <div className={css({ display: "grid", gap: "0.375rem" })}>{node.choices.map((choice) => <label key={choice.id} className={css({ display: "flex", alignItems: "center", gap: "0.5rem" })}><input disabled={disabled || completed} type={multiple ? "checkbox" : "radio"} name={node.id} checked={selected.includes(choice.id)} onChange={() => setSelected((current) => multiple ? current.includes(choice.id) ? current.filter((id) => id !== choice.id) : [...current, choice.id] : [choice.id])} />{choice.label}</label>)}</div>
					: node.kind === "slider" ? <div className={css({ display: "grid", gap: "0.375rem" })}><input disabled={disabled || completed} type="range" min={node.min ?? 0} max={node.max ?? 100} step={node.step ?? 1} value={answer || node.min || 0} onChange={(event) => setAnswer(event.currentTarget.value)} /><output>{answer || node.min || 0}</output></div>
						: <textarea disabled={disabled || completed} className={input} value={answer} onChange={(event) => setAnswer(event.currentTarget.value)} placeholder="Type your answer" />}
		{node.hint ? <small>{node.hint}</small> : null}
		{completed ? <p role="status">Answer saved.</p> : <button className={button} type="button" disabled={disabled || !ready} onClick={submit}>Submit answer</button>}
	</fieldset>;
}

function Checklist({ title, nodeId, items, actionType, disabled, onAction }: { title: string; nodeId: string; items: Array<{ id: string; title: string; done: boolean }>; actionType: "complete-goal-step" | "complete-plan-item"; disabled: boolean; onAction?: (event: SharedUiActionEvent) => boolean }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{items.map((item) => <label key={item.id} className={css({ display: "flex", gap: "0.5rem" })}><input disabled={disabled || (actionType === "complete-goal-step" && item.done)} type="checkbox" checked={item.done} onChange={() => onAction?.({ intent: actionType === "complete-goal-step" ? { type: actionType, nodeId, stepId: item.id } : { type: actionType, nodeId, itemId: item.id, completed: !item.done }, humanFriendlyMessage: `${item.done ? "Reopened" : "Completed"}: ${item.title}` })} />{item.title}</label>)}</div>;
}

function Plan({ nodeId, title, overview, items, disabled, onAction }: { nodeId: string; title: string; overview?: string; items: UiStudyPlanItem[]; disabled: boolean; onAction?: (event: SharedUiActionEvent) => boolean }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{overview ? <MarkdownBlock content={overview} /> : null}<PlanItems nodeId={nodeId} items={items} disabled={disabled} onAction={onAction} /></div>;
}

function PlanItems({ nodeId, items, disabled, onAction }: { nodeId: string; items: UiStudyPlanItem[]; disabled: boolean; onAction?: (event: SharedUiActionEvent) => boolean }) {
	return <ul className={css({ display: "grid", gap: "0.5rem", paddingLeft: "1rem" })}>{items.map((item) => <li key={item.id}><Checklist title={item.title} nodeId={nodeId} items={[{ id: item.id, title: item.detail ?? item.title, done: item.status === "done" }]} actionType="complete-plan-item" disabled={disabled} onAction={onAction} />{item.children ? <PlanItems nodeId={nodeId} items={item.children} disabled={disabled} onAction={onAction} /> : null}</li>)}</ul>;
}

function Notes({ node, disabled, onAction }: { node: Extract<UiDocumentNode, { type: "notes" }>; disabled: boolean; onAction?: (event: SharedUiActionEvent) => boolean }) {
	const [value, setValue] = useState(node.value);
	return <div className={section}><label htmlFor={node.id} className={css({ fontWeight: 700 })}>{node.title}</label><textarea disabled={disabled} id={node.id} className={input} value={value} placeholder={node.placeholder} onChange={(event) => setValue(event.currentTarget.value)} /><button disabled={disabled} className={button} type="button" onClick={() => onAction?.({ intent: { type: "update-notes", nodeId: node.id, value }, humanFriendlyMessage: `Updated ${node.title}` })}>Save notes</button></div>;
}

function Deck({ node, receipts, disabled, onAction }: { node: Extract<UiDocumentNode, { type: "deck" }>; receipts: UiActionReceipt[]; disabled: boolean; onAction?: (event: SharedUiActionEvent) => boolean }) {
	const [index, setIndex] = useState(() => receipts.length % Math.max(node.cards.length, 1));
	const [revealed, setRevealed] = useState(false);
	const card = node.cards[index];
	if (!card) return <div className={section}>This deck has no cards.</div>;
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{node.title}</h4>{receipts.length > 0 ? <small>{receipts.length} rating{receipts.length === 1 ? "" : "s"} saved.</small> : null}<button disabled={disabled} className={button} type="button" onClick={() => setRevealed((value) => !value)}>{revealed ? card.back : card.front}</button>{revealed ? <div className={css({ display: "flex", flexWrap: "wrap", gap: "0.375rem" })}>{["Again", "Hard", "Good", "Easy"].map((label, rating) => <button disabled={disabled} key={label} className={button} type="button" onClick={() => { const saved = onAction?.({ intent: { type: "rate-card", nodeId: node.id, cardId: card.id, rating: rating as 0 | 1 | 2 | 3 }, humanFriendlyMessage: `${label}: ${card.front}` }); if (saved) { setRevealed(false); setIndex((index + 1) % node.cards.length); } }}>{label}</button>)}</div> : null}</div>;
}

function Resource({ title, content, uri, markdown = false }: { title: string; content?: string; uri?: string; markdown?: boolean }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{content ? markdown ? <MarkdownBlock content={content} /> : <pre className={css({ overflowX: "auto", whiteSpace: "pre-wrap" })}>{content}</pre> : null}{uri ? <a className={button} href={uri} target="_blank" rel="noreferrer">Open resource</a> : null}</div>;
}

function Media({ node }: { node: Extract<UiDocumentNode, { type: "media" }> }) {
	const [failed, setFailed] = useState(() => intentionallyUnavailable(node.resource.uri));
	if (failed) return <UnavailableResource title={node.resource.title} uri={node.resource.uri} kind={node.kind} />;
	if (node.kind === "audio") return <div className={section}><strong>{node.resource.title}</strong><audio controls src={node.resource.uri} onError={() => setFailed(true)} /></div>;
	if (node.kind === "video") return <div className={section}><strong>{node.resource.title}</strong><video controls src={node.resource.uri} onError={() => setFailed(true)} className={css({ maxWidth: "100%" })} /></div>;
	return <Resource title={node.resource.title} uri={node.resource.uri} content="Animation opens only from its validated resource URL." />;
}

function intentionallyUnavailable(uri: string | undefined): boolean {
	if (!uri) return true;
	try {
		return new URL(uri).hostname.endsWith(".invalid");
	} catch {
		return true;
	}
}

function UnavailableResource({ title, uri, kind }: { title: string; uri?: string; kind: string }) {
	return <div className={section} role="status"><strong>{title}</strong><p>This {kind} resource is unavailable here. The lesson remains usable.</p>{uri && !intentionallyUnavailable(uri) ? <a className={button} href={uri} target="_blank" rel="noreferrer">Open source</a> : null}</div>;
}

function RemoteImage({ node }: { node: Extract<UiDocumentNode, { type: "image" }> }) {
	const [failed, setFailed] = useState(() => intentionallyUnavailable(node.resource.uri));
	if (failed) return <UnavailableResource title={node.resource.title} uri={node.resource.uri} kind="image" />;
	return <figure className={section}><img src={node.resource.uri} alt={node.alt} onError={() => setFailed(true)} className={css({ maxWidth: "100%", borderRadius: "0.5rem" })} /><figcaption>{node.resource.title}</figcaption></figure>;
}
import { useState } from "react";
import {
	MARKDOWN_PARITY_FIXTURE,
	OPENUI_JSON_PARITY_FIXTURE,
} from "@keating/learner-contracts";
import { css } from "../../styled-system/css";
import { MarkdownBlock } from "../components/MarkdownBlock";
import {
	KeatingOpenUIActionProvider,
	KeatingOpenUIRenderer,
} from "../keating/openui/renderer";
import { sharedUiActionStateKey } from "../keating/openui/shared-actions";
import type { KeatingOpenUIAction } from "../keating/openui/types";

const page = css({ minHeight: "100vh", background: "var(--background)", color: "var(--foreground)", padding: "1rem", sm: { padding: "2rem" } });
